zA(a){return""+a+" \u0430\u043b\u044c\u0431\u043e\u043c\u043e\u0432"},
ghS(){return B.alg},
xC(a){return""+A.bj(a)+" "+B.ahj[A.aQ(a)]+" "+A.ap(a)+", "+B.agD[A.ig(a)-1]},
nc(a){return"\u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0441 "+a},
